import { expect, test, uniqueName } from "../../fixtures";

test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
  const globex = await apiAs("otherTenant");
  const vendorRes = await globex.post("/api/vendors", {
    data: {
      name: uniqueName("Globex Vendor"),
      category: "services",
      contact_email: `ap-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@globex-procurement.com`,
    },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const vendor = await vendorRes.json();

  const uploadRes = await globex.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.pdf", mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 test w9") },
    },
  });
  expect(uploadRes.status(), await uploadRes.text()).toBe(201);
  const doc = await uploadRes.json();

  const member = await apiAs("member");
  const res = await member.get(`/api/documents/${doc.id}`);
  expect(res.status(), await res.text()).toBe(404);
  const body = await res.json();
  expect(body.error?.code, await res.text()).toBe("document_not_found");
});
